INSTR = {
'Band_Biceps_Curl': ['Stand on the middle of the band, feet hip-width, holding the handles palms forward.', 'Keep elbows pinned to your sides and curl up until the forearms are vertical.', 'Squeeze at the top, then lower slowly (2–3 s) to full arm extension.'],
'Band_Face_Away_Curl': ['Anchor the band low behind you (door anchor) and step forward so the working arm is pulled slightly behind your torso.', 'Keep the elbow behind your body and curl the handle toward your shoulder.', 'Lower slowly into the stretch; do all reps on one arm, then switch.'],
'Band_Triceps_Pushdown': ['Anchor the band high (top of a door). Hold the ends with elbows bent at your sides.', 'Keeping upper arms still, push down until the elbows are fully straight.', 'Pause, then let the hands rise back to about chest height under control.'],
'Band_Overhead_Triceps_Extension': ['Stand on the band (or anchor it low behind you) and hold it behind your head, elbows pointing up.', 'Extend the elbows to press the hands overhead, keeping upper arms close to your head.', 'Lower behind the head slowly for a deep stretch.'],
'Band_Triceps_Kickback': ['Anchor the band low in front, hinge forward ~45°, upper arm against your side.', 'Straighten the elbow so the hand travels back past your hip.', 'Squeeze the triceps at lockout, return slowly; keep the upper arm still.'],
'Bench_Dip': ['Sit on the edge of a sturdy chair, hands beside your hips, slide your hips off the edge.', 'Bend the elbows to about 90° keeping your back close to the chair.', 'Press back up; keep knees bent to make it easier. Stop if the front of the shoulder hurts.'],
'Diamond_Push_Up': ['Start in a push-up position with hands close together under the chest.', 'Lower with elbows tucked close to the body until the chest nearly touches your hands.', 'Press back up. Do it from the knees or with hands on a bench to make it easier.'],
'Farmer_Carry_Hold': ['Hold a heavy dumbbell in each hand at your sides, shoulders down and back.', 'Stand tall (hold) or walk with short, steady steps for the set time.', 'Squeeze the handles hard, brace your core, and do not let the weights swing.'],
'DB_Reverse_Wrist_Curl_Std': ['Sit with forearm on your thigh, palm down, band under your foot and in your hand.', 'Lift the back of the hand up (wrist extension) as far as comfortable.', 'Lower slowly; keep the forearm still.'],
'Band_Grip_Squeeze': ['Loop a light band around your fingers and thumb (or squeeze a rolled band).', 'Open the fingers against the band (extension) or squeeze hard (flexion).', 'Do high reps for grip endurance and elbow health.'],
'DB_Lean_In_Lateral': ['Hold a post or door frame with one hand and lean your body toward it slightly.', 'With a dumbbell in the free hand, raise the arm out to the side to shoulder height, elbow soft.', 'Lower slowly. The lean keeps tension on the side delt at the bottom.'],
'Band_Face_Pull': ['Anchor the band at face height. Hold both ends with palms facing each other.', 'Pull toward your face, splitting the hands apart and rotating so the knuckles point back.', 'Squeeze the rear delts/upper back, then return slowly.'],
'Band_Y_Raise': ['Stand on a band, crossing the ends in front of you, thumbs up.', 'Raise the arms up and out into a "Y" shape to about head height.', 'Lower slowly; keep the shoulders down away from the ears.'],
'DB_Halo': ['Hold one dumbbell by the bell with both hands at chest height.', 'Circle it slowly around your head, keeping it close, elbows soft.', 'Reverse direction each set; keep the core tight and ribs down.'],
'Band_Upright_Shrug': ['Stand on the band, holding the handles at your sides.', 'Shrug the shoulders straight up toward the ears.', 'Pause, then lower slowly. Don\'t roll the shoulders.'],
'Push_Up': ['Hands slightly wider than shoulders, body in a straight line from head to heels.', 'Lower until the chest is near the floor, elbows ~45° from your body.', 'Press back up without letting the hips sag.'],
'Incline_Push_Up': ['Place hands on a bench, table or wall-height surface; walk feet back into a straight line.', 'Lower the chest to the edge with elbows ~45°.', 'Push back up. Lower surface = harder.'],
'Knee_Push_Up': ['Push-up position from the knees, body straight from head to knees.', 'Lower the chest toward the floor, elbows ~45°.', 'Press up. Use a soft mat under the knees.'],
'Wall_Push_Up': ['Stand arm\'s length from a wall, hands on the wall at shoulder height.', 'Bend the elbows to bring the chest toward the wall.', 'Push back. Step further away to make it harder.'],
'Deficit_Push_Up_DB': ['Set two hex dumbbells on the floor and grip the handles, body in a push-up line.', 'Lower the chest below hand level for an extra stretch.', 'Press up. Make sure the dumbbells cannot roll.'],
'Banded_Push_Up': ['Loop a band across your upper back and hold the ends under your palms.', 'Do a normal push-up; the band adds resistance at the top.', 'Use a light band first and keep a straight body line.'],
'Band_Chest_Fly': ['Anchor the band behind you at chest height, a handle in each hand, arms out wide.', 'With a slight elbow bend, bring the hands together in front of your chest.', 'Return slowly until you feel a chest stretch.'],
'Band_Lat_Pulldown': ['Anchor the band high (top of a door). Kneel or sit facing it, arms extended overhead.', 'Pull the elbows down to your sides, driving them toward your back pockets.', 'Squeeze the lats, then let the arms rise slowly to a full stretch.'],
'Band_Single_Arm_Pulldown': ['Anchor the band high and half-kneel facing it, one hand on the handle.', 'Pull the elbow down to your side, keeping the torso still.', 'Return slowly to a full overhead stretch; finish one side then switch.'],
'Band_Straight_Arm_Pulldown': ['Anchor the band high, stand back, arms straight in front at shoulder height.', 'Keeping elbows nearly straight, sweep the hands down to your thighs.', 'Squeeze the lats, return slowly.'],
'Band_Assisted_Pull_Up': ['Loop a band over a pull-up bar and place a knee or foot in it.', 'From a dead hang, pull your chest toward the bar.', 'Lower all the way down slowly. Use a thinner band as you get stronger.'],
'Band_Seated_Row': ['Sit with legs extended, band looped around your feet, holding the ends.', 'Sit tall and pull the hands toward your lower ribs, squeezing the shoulder blades.', 'Return slowly until the arms are straight and the shoulders stretch forward.'],
'Band_Single_Arm_Row': ['Anchor the band at chest height, stand in a staggered stance holding one handle.', 'Row the elbow back past your torso.', 'Return slowly; keep the hips square.'],
'Renegade_Row': ['Plank on two dumbbells, feet wide for balance.', 'Row one dumbbell to your hip without twisting the hips.', 'Lower and alternate. Treat it as a core exercise.'],
'Superman': ['Lie face down, arms extended overhead.', 'Lift the arms, chest and legs a few inches off the floor.', 'Hold 2–3 s, lower with control.'],
'Bird_Dog': ['Start on hands and knees, hands under shoulders, knees under hips.', 'Extend the opposite arm and leg straight out, keeping hips level and back flat.', 'Hold 2–3 s, return and switch sides.'],
'Band_Deadlift': ['Stand on the middle of the band, hinge down and grab the handles.', 'Drive through the floor and stand tall, hips through.', 'Hinge back down with a flat back.'],
'Dead_Bug': ['Lie on your back, arms up, hips and knees bent at 90°.', 'Press your lower back into the floor and slowly extend the opposite arm and leg.', 'Return and switch sides; keep the lower back flat throughout.'],
'Forearm_Plank': ['Forearms on the floor, elbows under shoulders, body straight from head to heels.', 'Brace the abs and squeeze the glutes.', 'Hold for time; breathe steadily. Drop to the knees to make it easier.'],
'Side_Plank': ['Lie on your side, forearm under the shoulder, legs stacked.', 'Lift the hips so the body forms a straight line.', 'Hold for time; bottom knee down to make it easier.'],
'Band_Pallof_Press': ['Anchor the band at chest height, stand side-on, holding the band at the chest.', 'Press the hands straight out and resist the band pulling you to rotate.', 'Hold 2 s, bring the hands back; do both sides.'],
'Band_Woodchop': ['Anchor the band high to one side, hold it with both hands.', 'Pull diagonally down and across the body, rotating through the torso and pivoting the back foot.', 'Return slowly; do both sides.'],
'DB_Russian_Twist': ['Sit with knees bent, lean back slightly, holding a light dumbbell at the chest.', 'Rotate the torso slowly to one side, then the other.', 'Keep the spine long; feet can stay on the floor.'],
'Bicycle_Crunch': ['Lie on your back, hands lightly behind the head, knees lifted.', 'Bring the opposite elbow toward the knee as the other leg extends.', 'Alternate slowly and with control, without pulling on the neck.'],
'DB_Weighted_Crunch': ['Lie on your back, knees bent, holding a dumbbell on your chest.', 'Curl the shoulders off the floor by crunching the ribs toward the pelvis.', 'Lower slowly.'],
'Band_Kneeling_Crunch': ['Anchor the band high, kneel facing it, holding the band beside your head.', 'Crunch down by rounding the spine, bringing the elbows toward the thighs.', 'Return slowly; keep the hips still.'],
'Reverse_Crunch': ['Lie on your back, hands by your sides, knees bent at 90°.', 'Curl the hips off the floor, bringing the knees toward the chest.', 'Lower slowly without swinging.'],
'DB_Suitcase_Carry': ['Hold one heavy dumbbell at your side.', 'Walk tall without leaning toward the weight.', 'Switch hands each set.'],
'DB_Goblet_Squat': ['Hold one dumbbell vertically at your chest, feet shoulder-width.', 'Sit down between the heels to a box/chair, only as deep as pain-free.', 'Drive up through the heels, knees tracking over toes.'],
'Wall_Sit': ['Back against a wall, slide down until the knees are at a comfortable angle (not deeper than pain-free).', 'Keep the knees over the ankles and weight in the heels.', 'Hold for time.'],
'Sit_To_Stand': ['Sit on a chair, feet flat, arms crossed or reaching forward.', 'Stand up by driving through the heels, without using your hands.', 'Sit back down slowly. Use a higher seat if the knee complains.'],
'Band_Reverse_Nordic': ['Kneel upright with a band anchored in front at chest height for assistance.', 'Lean the torso back in a straight line from knees to head.', 'Return using the quads. High knee stress, so skip it with knee pain.'],
'DB_Bulgarian_Split_Squat': ['Stand in front of a bench, rear foot on the bench, dumbbells at your sides.', 'Lower the back knee toward the floor, front knee over the toes.', 'Drive up through the front heel. Go shallow if your knee hurts.'],
'DB_Walking_Lunge': ['Hold dumbbells at your sides.', 'Step forward and lower the back knee toward the floor.', 'Push through the front heel and step through into the next lunge.'],
'DB_Hip_Thrust': ['Sit with upper back against a bench, a dumbbell on your hip crease.', 'Drive through the heels to raise the hips until the body is flat from knees to shoulders.', 'Squeeze the glutes, then lower slowly.'],
'DB_Single_Leg_Hip_Thrust': ['Upper back on a bench, one foot planted, dumbbell on the working hip.', 'Drive through the heel to lift the hips level.', 'Lower slowly; finish one side then switch.'],
'Glute_Bridge': ['Lie on your back, knees bent, feet flat, dumbbell resting on the hips.', 'Drive through the heels and lift the hips until the body is straight from knees to shoulders.', 'Squeeze the glutes 1–2 s, lower slowly.'],
'Single_Leg_Glute_Bridge': ['Lie on your back, one knee bent and the other leg extended.', 'Drive through the planted heel to lift the hips.', 'Lower slowly; keep the hips level.'],
'Band_Glute_Kickback': ['Loop the band around your ankles or anchor it low; hold a support.', 'Kick one leg straight back, squeezing the glute, without arching the low back.', 'Return slowly; switch legs.'],
'Banded_Hip_Abduction': ['Sit on a chair with a band just above the knees.', 'Push the knees out against the band.', 'Pause, return slowly. Lean forward slightly for more glute.'],
'Clamshell': ['Lie on your side, knees bent, band above the knees.', 'Keeping the feet together, lift the top knee.', 'Lower slowly; don\'t roll the hips back.'],
'Side_Lying_Leg_Raise': ['Lie on your side, bottom knee bent, top leg straight.', 'Lift the top leg slightly behind the body line.', 'Lower slowly. Add an ankle band to progress.'],
'Lateral_Band_Walk': ['Band above the knees or around the ankles, slight squat.', 'Step sideways, keeping tension on the band and the knees pushed out.', 'Do equal steps each direction.'],
'Band_Hamstring_Curl': ['Lie face down with the band anchored low to a door/post and looped around the ankle.', 'Curl the heel toward the glute.', 'Lower slowly. Stop if it irritates the knee.'],
'DB_Single_Leg_RDL': ['Hold a dumbbell, stand on one leg with a soft knee.', 'Hinge forward, extending the free leg back, until the torso is near horizontal.', 'Return by driving the hips forward; hold a wall for balance if needed.'],
'DB_Hip_Hinge': ['Hold light dumbbells in front of the thighs, soft knees.', 'Push the hips back, sliding the weights down the thighs with a flat back.', 'Stand up by squeezing the glutes.'],
'DB_Thruster': ['Hold dumbbells at the shoulders.', 'Do a partial squat, then drive up and press the weights overhead in one motion.', 'Lower to the shoulders and repeat. Keep the squat shallow for the knee.'],
'DB_Push_Press': ['Dumbbells at the shoulders, feet hip-width.', 'Do a small knee dip, then drive up and press overhead.', 'Lower under control.'],
'DB_Man_Maker': ['Hands on dumbbells in a plank, do a push-up and a row on each side.', 'Jump or step the feet in, clean the weights to the shoulders.', 'Press overhead. Step back instead of jumping to protect the knee.'],
'DB_Snatch': ['Dumbbell between the feet, hinge and grab it with one hand.', 'Explode up with the hips and pull the weight overhead in one motion, punching through at the top.', 'Lower in two steps (shoulder, then hip). Start light.'],
'DB_Turkish_Get_Up': ['Lie on your back holding a dumbbell straight up in one hand.', 'Roll to the elbow, then to the hand, bridge the hips, sweep the leg through and stand up, keeping the arm locked overhead.', 'Reverse the steps slowly. Learn it with no weight first.'],
'DB_Windmill': ['Dumbbell overhead in one hand, feet angled away from that side.', 'Push the hip out and slide the free hand down the leg, eyes on the weight.', 'Return to standing; keep the arm vertical.'],
'DB_Squat_To_Press': ['Dumbbells at the shoulders.', 'Squat (partial for the knee), stand, then press overhead.', 'Lower and repeat.'],
'March_Arm_Drive': ['March in place, driving the knees up to hip height.', 'Pump the arms hard.', 'Keep it fast but low-impact; no jumping.'],
'Band_Fast_Punches': ['Anchor a light band behind you, holding the ends at the shoulders.', 'Punch alternately and quickly, rotating slightly.', 'Keep the core braced.'],
'Standing_Knee_Lift': ['Stand tall, hands on the hips or a support.', 'Lift one knee toward the chest under control.', 'Lower and alternate.'],
'Iron_Cross': ['Hold light dumbbells in front of the thighs.', 'Squat partially while raising the dumbbells forward to shoulder height.', 'Stand and lower the weights; keep it light and controlled.'],
}
